const body = $input.first().json.body || $input.first().json;
const data = body.data || {};

const remoteJid = data.key?.remoteJid || '';
const senderName = data.pushName || 'الزائر الكريم';
const text = data.text || '';
const messageType = data.messageType || 'text';
const mediaBase64 = data.mediaBase64 || null;
const mimeType = data.mimeType || null;

if (!text && !mediaBase64) return [];

return [{
  json: {
    phone: remoteJid,
    remoteJid,
    text,
    senderName,
    messageType,
    mediaBase64,
    mimeType
  }
}];

const fs = require('fs');
const eventsPath = '/tmp/mosque_events.txt';
const data = $input.first().json;

let eventsContent = '';
try {
  if (fs.existsSync(eventsPath)) {
    eventsContent = fs.readFileSync(eventsPath, 'utf8');
  }
} catch (e) {}

return [{ json: { ...data, eventsContent } }];

